import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
def get_cambodia_geom():
    try:
        fc = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
        cmb = fc.filter(ee.Filter.eq('country_na', 'Cambodia'))
        if cmb.size().getInfo() == 0:
            cmb = fc.filter(ee.Filter.eq('name', 'Cambodia'))
        if cmb.size().getInfo() == 0:
            # Fallback bbox (roughly Cambodia)
            geom = ee.Geometry.Rectangle([102.0, 10.2, 107.8, 14.8])
            return geom, "BBox fallback"
        return cmb.geometry(), "USDOS/LSIB_SIMPLE/2017"
    except Exception as e:
        # As last resort, bbox
        geom = ee.Geometry.Rectangle([102.0, 10.2, 107.8, 14.8])
        return geom, "BBox fallback"

geom, region_src = get_cambodia_geom()

periods = {
    "Aug2017": ("2017-08-01", "2017-09-01"),
    "Feb2018": ("2018-02-01", "2018-03-01"),
}

# 2. Data Acquisition & Check, with dataset fallbacks
def get_collection_for_period(start, end, geom):
    dataset_ids = ['MODIS/061/MCD14A1', 'MODIS/006/MCD14A1']
    last_error = None
    for ds in dataset_ids:
        try:
            col = ee.ImageCollection(ds).filterDate(start, end).filterBounds(geom)
            size = col.size().getInfo()
            if size > 0:
                return col, ds, size
        except Exception as e:
            last_error = e
            continue
    # Attempt widened window if zero
    try:
        col = ee.ImageCollection(dataset_ids[0]).filterDate(
            ee.Date(start).advance(-3, 'day'), ee.Date(end).advance(3, 'day')
        ).filterBounds(geom)
        size = col.size().getInfo()
        if size > 0:
            return col, dataset_ids[0], size
    except Exception as e:
        last_error = e
    if last_error:
        print(f"Dataset error: {str(last_error)[:100]}")
        print("<answer>D</answer>")
        sys.exit(0)
    return None, None, 0

def valid_pixel_count(col, geom):
    # Count any valid FireMask pixels available across the period
    mosaic = col.select('FireMask').mosaic()
    d = mosaic.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=1000,
        maxPixels=1e10,
    )
    return d.get('FireMask')

def monthly_fire_count(col, geom):
    def per_image(img):
        fire = img.select('FireMask').gte(7).rename('fire').selfMask()
        cnt = fire.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=1000,
            maxPixels=1e10,
        ).get('fire')
        return img.set('firecount', cnt)
    col2 = col.map(per_image)
    total = ee.Number(col2.aggregate_sum('firecount'))
    return total, col2.size()

results = {}
dataset_used = None

# Process each period
for label, (start, end) in periods.items():
    col, ds, size = get_collection_for_period(start, end, geom)
    if size == 0 or col is None:
        print(f"{label} Images: 0")
        print("<answer>C1</answer>")
        sys.exit(0)
    if dataset_used is None:
        dataset_used = ds
    # Validate valid pixels
    vp = valid_pixel_count(col, geom)
    vp_val = vp.getInfo()
    if vp_val is None:
        print(f"{label} ValidPix: None")
        print("<answer>C3</answer>")
        sys.exit(0)
    if vp_val == 0:
        print(f"{label} Images: {size}, ValidPix: 0")
        print("<answer>C2</answer>")
        sys.exit(0)
    # Fire counts
    total_fire, imgcount = monthly_fire_count(col, geom)
    tf = total_fire.getInfo()
    ic = imgcount.getInfo()
    if tf is None or (isinstance(tf, float) and (math.isnan(tf) or math.isinf(tf))):
        print(f"{label} Images: {ic}, FirePx: None")
        print("<answer>C3</answer>")
        sys.exit(0)
    results[label] = {'images': ic, 'validpix': int(vp_val), 'firepx': int(tf)}

# 5. Validation & Final Answer
print(f"Region: Cambodia ({region_src})")
print(f"Dataset: {dataset_used}")
print(f"Aug2017 Images: {results['Aug2017']['images']}, ValidPix: {results['Aug2017']['validpix']}, FirePx: {results['Aug2017']['firepx']}")
print(f"Feb2018 Images: {results['Feb2018']['images']}, ValidPix: {results['Feb2018']['validpix']}, FirePx: {results['Feb2018']['firepx']}")
delta = results['Feb2018']['firepx'] - results['Aug2017']['firepx']
print(f"Delta (Feb2018 - Aug2017) FirePx: {delta}")

if results['Feb2018']['firepx'] > results['Aug2017']['firepx']:
    print("A: Yes")
else:
    print("B: No")
